"""Линии: синус и косинус с подписями и сеткой."""
import numpy as np


def draw(fig):
    x = np.linspace(0, 2 * np.pi, 200)
    ax = fig.add_subplot()
    ax.plot(x, np.sin(x), label="sin x")
    ax.plot(x, np.cos(x), "--", label="cos x")
    ax.set_title("Синус и косинус")
    ax.set_xlabel("x, рад")
    ax.grid(alpha=0.3)
    ax.legend()


if __name__ == "__main__":
    from mpldemo import run
    run(draw)
